    case 'user': return '#2563eb';
    case 'reason': return '#4f46e5';
    case 'observe': return '#0369a1';
    case 'respond': return '#15803d';
    case 'delegate': return '#c2410c';
    case 'worker': return '#7c3aed';
    case 'wake': return '#b45309';
    default: return '#6b7280';
  }
}

