  "path": "/home/user/work/agents-visualized/app/src/views/sankey.ts",
  "content": "import * as d3 from 'd3';
import { sankey, sankeyLinkHorizontal, sankeyJustify, type SankeyNode, type SankeyLink } from 'd3-sankey';
import type { FlowLink, FlowNode, LoopsDataset } from '../types';
import { fmtInt, stageColor, stageLabel } from '../format';
import { nodeTip, tooltip, type TipContent } from '../tooltip';
import { flowExamples } from '../data';
import { el, makeRoving, onResize } from '../util';

type SNode = SankeyNode<FlowNode, FlowLink>;
type SLink = SankeyLink<FlowNode, FlowLink>;

/** Canonical left-to-right order of stages; tool:* share one rank. */
const STAGE_RANK: Record<string, number> = { user: 0, wake: 0, reason: 1, delegate: 2, worker: 3, observe: 3, respond: 4 };
const rank = (stage: string): number => (stage.startsWith('tool:') ? 2 : STAGE_RANK[stage] ?? 2);

/**
 * d3-sankey cannot lay out cycles. Observed loops (observe→reason, wake→…)
 * are real, so instead of dropping them we split links into a forward DAG
 * (laid out by d3-sankey) and "loop-back" links drawn as return arcs above the
 * diagram, scaled by the same width scale.
 */
function splitCycles(nodes: FlowNode[], links: FlowLink[]): { forward: FlowLink[]; back: FlowLink[] } {
  const byId = new Map(nodes.map((n) => [n.id, n]));
  const adj = new Map<string, Set<string>>();
  const reaches = (from: string, to: string): boolean => {
    const seen = new Set<string>([from]);
    const stack = [from];
    while (stack.length) {
      const cur = stack.pop()!;
      if (cur === to) return true;
      for (const nx of adj.get(cur) ?? []) if (!seen.has(nx)) { seen.add(nx); stack.push(nx); }
    }
    return false;
  };
  const sorted = [...links].sort((a, b) => {
    const da = rank(byId.get(a.target)?.stage ?? '') - rank(byId.get(a.source)?.stage ?? '');
    const db = rank(byId.get(b.target)?.stage ?? '') - rank(byId.get(b.source)?.stage ?? '');
    return db - da || b.value - a.value; // forward-most, then heaviest first
  });
  const forward: FlowLink[] = [], back: FlowLink[] = [];
  for (const l of sorted) {
    if (l.source === l.target || reaches(l.target, l.source)) { back.push(l); continue; }
    forward.push(l);
    (adj.get(l.source) ?? adj.set(l.source, new Set()).get(l.source)!).add(l.target);
  }
  return { forward, back };
}

export function renderSankey(container: HTMLElement, ds: LoopsDataset): void {
  const { nodes, links } = ds.flows;
  container.replaceChildren();
  if (!nodes.length) { container.append(el('p', { class: 'muted' }, 'No flow data.')); return; }

  const examples = flowExamples(ds.hierarchy);
  const { forward, back } = splitCycles(nodes, links);
  const nodeById = new Map(nodes.map((n) => [n.id, n]));

  const legend = el('p', { class: 'view-note' },
    `Observed transitions between step stages. Ribbon thickness = number of transitions. `,
    el('strong', {}, `${fmtInt(back.length)} loop-back edge${back.length === 1 ? '' : 's'}`),
    ` (repeat cycles such as observe → reason) are drawn as dashed return arcs above the diagram because a Sankey layout is acyclic.`);
  const host = el('div', { class: 'chart-host', role: 'group', 'aria-label': 'Loop Sankey diagram; use arrow keys to move between nodes and ribbons' });
  container.append(legend, host);

  const draw = (width: number): void => {
    host.replaceChildren();
    const height = Math.max(420, Math.min(760, nodes.length * 44));
    const backGutter = back.length ? 70 : 0;
    const margin = { top: 16 + backGutter, right: 150, bottom: 16, left: 16 };
    const gen = sankey<FlowNode, FlowLink>()
      .nodeId((d) => d.id)
      .nodeWidth(16)
      .nodePadding(14)
      .nodeAlign(sankeyJustify)
      .nodeSort((a, b) => rank(a.stage) - rank(b.stage) || d3.descending(a.value ?? 0, b.value ?? 0))
      .extent([[margin.left, margin.top], [width - margin.right, height - margin.bottom]]);
    const graph = gen({ nodes: nodes.map((n) => ({ ...n })), links: forward.map((l) => ({ ...l })) });

    const svg = d3.create('svg')
      .attr('viewBox', `0 0 ${width} ${height}`)
      .attr('width', width).attr('height', height)
      .attr('role', 'img')
      .attr('aria-label', 'Sankey of observed step-stage transitions');
    svg.append('title').text('Observed step-stage transitions (Sankey)');

    const widthScale = d3.scaleLinear().domain([0, d3.max(links, (l) => l.value) ?? 1]).range([1.5, 24]);

    // Forward ribbons
    const linkG = svg.append('g').attr('fill', 'none');
    linkG.selectAll<SVGPathElement, SLink>('path').data(graph.links).join('path')
      .attr('class', 'sankey-link')
      .attr('d', sankeyLinkHorizontal())
      .attr('stroke', (d) => stageColor((d.source as SNode).stage))
      .attr('stroke-width', (d) => Math.max(1.5, d.width ?? 1))
      .attr('data-tip', 'link')
      .attr('data-key', (d) => `${(d.source as SNode).id}->${(d.target as SNode).id}`)
      .attr('tabindex', -1)
      .attr('role', 'button')
