  "content": "/* ------------------------------------------------------------------------
   Theme. `color-scheme` opts UA widgets/scrollbars into both schemes; every
   colour is a light-dark() pair so the dark theme needs no duplicated rules
   (dark-mode guide). The <select id="theme"> only flips `color-scheme` on
   <html>, which light-dark() follows automatically.
   ------------------------------------------------------------------------ */
:root {
  color-scheme: light dark;
  --bg: light-dark(#ffffff, #0f1115);
  --bg-2: light-dark(#f5f6f8, #171a21);
  --bg-3: light-dark(#e9ebef, #20242d);
  --fg: light-dark(#111318, #e8eaf0);
  --fg-muted: light-dark(#5b6270, #a3abb8);
  --border: light-dark(#d5d9e0, #2d323d);
  --accent: light-dark(#2563eb, #7aa2ff);
  --focus: light-dark(#0b57d0, #9cc0ff);
  --warn-bg: light-dark(#fff4d6, #3a2f12);
  --warn-fg: light-dark(#6b4e00, #ffd97a);
  --err: light-dark(#b91c1c, #ff8a8a);
  --shadow: 0 8px 28px light-dark(rgb(0 0 0 / 0.14), rgb(0 0 0 / 0.6));

  /* Fluid type + space (fluid-scaling guide): clamp() with a viewport-based middle term */
  --step--1: clamp(0.78rem, 0.74rem + 0.2vw, 0.88rem);
  --step-0: clamp(0.95rem, 0.9rem + 0.25vw, 1.05rem);
  --step-1: clamp(1.15rem, 1.05rem + 0.5vw, 1.4rem);
  --step-2: clamp(1.5rem, 1.25rem + 1.2vw, 2.2rem);
  --space: clamp(0.75rem, 0.5rem + 1vw, 1.5rem);
  --radius: 8px;
  --font: system-ui, -apple-system, "Segoe UI", Roboto, Inter, sans-serif;
  --mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
}
/* Fallback for engines without light-dark(): a plain dark override */
@supports not (color: light-dark(#000, #fff)) {
  @media (prefers-color-scheme: dark) {
    :root { --bg: #0f1115; --bg-2: #171a21; --bg-3: #20242d; --fg: #e8eaf0; --fg-muted: #a3abb8; --border: #2d323d; --accent: #7aa2ff; --focus: #9cc0ff; --warn-bg: #3a2f12; --warn-fg: #ffd97a; --err: #ff8a8a; }
  }
}

*, *::before, *::after { box-sizing: border-box; }
html { font-family: var(--font); font-size: var(--step-0); line-height: 1.5; -webkit-text-size-adjust: 100%; }
body { margin: 0; background: var(--bg); color: var(--fg); min-block-size: 100dvh; }
h1 { font-size: var(--step-2); margin: 0 0 .25em; line-height: 1.15; }
h2 { font-size: var(--step-1); margin: 0 0 .25em; }
h3 { font-size: var(--step-0); margin: 1.5em 0 .5em; }
p { margin: 0 0 .75em; }
code { font-family: var(--mono); font-size: .92em; }
.muted { color: var(--fg-muted); }
.small { font-size: var(--step--1); }
.error { color: var(--err); }
.is-error { color: var(--err); font-weight: 600; }
.visually-hidden { position: absolute !important; inline-size: 1px; block-size: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

/* Focus: always visible, 2px offset ring, on HTML controls and SVG nodes alike (accessibility guide) */
:focus-visible { outline: 3px solid var(--focus); outline-offset: 2px; }
svg [tabindex]:focus-visible { outline: 3px solid var(--focus); outline-offset: 2px; }
svg [tabindex]:focus { outline: 3px solid var(--focus); outline-offset: 2px; } /* SVG focus-visible support is uneven; keep a plain :focus ring too */

.skip-link { position: absolute; inset-block-start: -100px; inset-inline-start: var(--space); background: var(--accent); color: #fff; padding: .5em 1em; border-radius: var(--radius); z-index: 10; }
.skip-link:focus { inset-block-start: var(--space); }

/* Layout */
.site-header, .source, main, .site-footer, .banner { inline-size: min(100% - 2 * var(--space), 1400px); margin-inline: auto; }
.site-header { display: flex; flex-wrap: wrap; gap: var(--space); justify-content: space-between; align-items: flex-start; padding-block: calc(var(--space) * 1.5) var(--space); }
.lede { max-inline-size: 70ch; color: var(--fg-muted); }
.header-tools select { font: inherit; padding: .35em .6em; border-radius: var(--radius); border: 1px solid var(--border); background: var(--bg-2); color: var(--fg); }

.banner { border: 1px solid var(--border); background: var(--bg-2); padding: .6em .9em; border-radius: var(--radius); margin-block-end: var(--space); }
.banner.is-warning { background: var(--warn-bg); color: var(--warn-fg); border-color: color-mix(in oklab, var(--warn-fg) 40%, transparent); }
.banner.is-error { color: var(--err); }

.source { background: var(--bg-2); border: 1px solid var(--border); border-radius: var(--radius); padding: var(--space); margin-block-end: var(--space); }
.source-text { white-space: pre-wrap; font-size: var(--step--1); line-height: 1.55; max-block-size: 12lh; overflow: auto; padding: .5em .75em; background: var(--bg); border-radius: 6px; border: 1px solid var(--border); }
.source-meta { display: grid; grid-template-columns: max-content 1fr; gap: .2em 1em; margin: .5em 0 0; font-size: var(--step--1); }
.source-meta dt { color: var(--fg-muted); }
.source-meta dd { margin: 0; overflow-wrap: anywhere; }

/* Tabs */
.tabs { display: flex; flex-wrap: wrap; gap: .25rem; border-block-end: 1px solid var(--border); margin-block-end: var(--space); }
