  "content": "import { chromium } from 'playwright';
import { mkdirSync } from 'node:fs';

const base = process.argv[2] ?? 'http://127.0.0.1:4173/';
const out = process.argv[3] ?? '/home/user/work/agents-visualized/app/screenshots';
mkdirSync(out, { recursive: true });

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1400, height: 900 } });
const errors = [];
page.on('pageerror', (e) => errors.push(`pageerror: ${e.message}`));
page.on('console', (m) => { if (m.type() === 'error' || m.type() === 'warning') errors.push(`console.${m.type()}: ${m.text()}`); });

await page.goto(base, { waitUntil: 'networkidle' });
await page.waitForSelector('#tablist [role=tab]');
console.log('banner:', (await page.textContent('#banner'))?.trim().slice(0, 160));
console.log('source:', (await page.textContent('#source-text'))?.trim().slice(0, 160));

const tabs = await page.$$('#tablist [role=tab]');
const report = [];
for (const tab of tabs) {
  const id = await tab.getAttribute('data-view');
  await tab.click();
  await page.waitForTimeout(400);
  const panel = page.locator(`#panel-${id}`);
  const svgCount = await panel.locator('svg').count();
  const tipTargets = await panel.locator('[data-tip]').count();
  const errText = await panel.locator('.error').count();
  // hover first target and see the tooltip open
  let tipOpen = false, tipTitle = '', focusTipOpen = false;
  const first = panel.locator('[data-tip]').first();
  if (tipTargets) {
    await first.scrollIntoViewIfNeeded();
    await first.hover();
    await page.waitForTimeout(150);
    tipOpen = await page.locator('.tip:popover-open, .tip.is-open').count() > 0;
    tipTitle = (await page.locator('.tip .tip-title').first().textContent().catch(() => ''))?.trim() ?? '';
    await page.mouse.move(5, 5);
    await page.waitForTimeout(300);
    // keyboard: focus the first target
    await first.focus();
    await page.waitForTimeout(150);
    focusTipOpen = await page.locator('.tip:popover-open, .tip.is-open').count() > 0;
    // arrow key moves focus
    await page.keyboard.press('ArrowRight');
